import axiosConfig from "../axiosConfig"
export const apiUserRegister = async ({email, password, confirmpassword, username, address, birthday, gender, career, workplace}) => {
    try {
        const response = await axiosConfig.post('/api/user/register', data);
        return response.data;
    } catch (error) {
        throw error.message;
    }
};

export const apiUserLogin = async (data) => {
    try {
        const response = await axiosConfig.post('/api/user/login', data);
        return response.data;
    } catch (error) {
        throw error.message;
    }
};
